import gurobipy as gp
from gurobipy import GRB
platforms = []
capacities = {}
genres = []
values = {}
requirements = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'resource_id' in v and 'resource_capacity' in v:
        pid = v['resource_id']
        platforms.append(pid)
        capacities[pid] = int(v['resource_capacity'])
    if 'item_name' in v and 'item_value' in v and ('resource_requirement' in v):
        gname = v['item_name']
        genres.append(gname)
        values[gname] = int(v['item_value'])
        requirements[gname] = int(v['resource_requirement'])
if set(capacities.keys()) != set(platforms):
    raise ValueError('Missing platform capacities')
if set(values.keys()) != set(genres) or set(requirements.keys()) != set(genres):
    raise ValueError('Missing genre values or requirements')
m = gp.Model('Game_Listing_Optimization')
x = m.addVars(platforms, genres, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[j] * x[i, j] for i in platforms for j in genres)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((requirements[j] * x[i, j] for j in genres)) <= capacities[i] for i in platforms), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')